import collections, hashlib, json
from pathlib import Path
root = Path('products/services/boamp-date-first-link-qa')
raw = (root / 'raw/recent.json').read_bytes()
feed = json.loads(raw)
records = feed['results']
terms = ('lien bris', 'liens morts', 'liens internes', 'audit de liens', 'redirection', 'migration de contenu', 'refonte du site', 'contrôle des liens', 'verification des liens', 'vérification des liens')
def walk(value, path):
    if isinstance(value, dict):
        for k, v in value.items():
            yield from walk(v, path + (k,))
    elif isinstance(value, list):
        for v in value:
            yield from walk(v, path + ('[]',))
    elif isinstance(value, str):
        yield '.'.join(path), value
        if value.lstrip().startswith(('{', '[')):
            try:
                embedded = json.loads(value)
            except ValueError:
                return
            yield from walk(embedded, path + ('embedded_json',))
rows = []
for record in records:
    fields = list(walk(record, ()))
    pointers = []
    for path, text in fields:
        folded = text.casefold()
        for term in terms:
            pos = folded.find(term)
            if pos >= 0:
                pointers.append({'field': path, 'term': term, 'excerpt': text[max(0, pos-45):pos+len(term)+65]})
    rows.append({'notice_id': record.get('idweb'), 'publication_date': record.get('dateparution'), 'response_deadline': record.get('datelimitereponse'), 'object': str(record.get('objet') or '')[:220], 'top_level_fields': sorted(record), 'string_field_paths': dict(collections.Counter(path for path, _ in fields)), 'scope_pointers': pointers[:12]})
report = {'source_sha256': hashlib.sha256(raw).hexdigest(), 'reported_total': feed.get('total_count'), 'returned_count': len(rows), 'rows_with_scope_pointers': sum(bool(row['scope_pointers']) for row in rows), 'records': rows, 'limitation': 'A lexical pointer requires original notice verification. An empty result covers this response and these phrases only.'}
out = root / 'director-nested-scope-readback.json'
out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
check = json.loads(out.read_text(encoding='utf-8'))
print(json.dumps({k: check[k] for k in ('source_sha256', 'reported_total', 'returned_count', 'rows_with_scope_pointers')}))
